@extends('layouts.app') @section('title','Pay for order #'.$order->id.' · '.$brand) @section('content')<div class="max-w-xl mx-auto"><h1 class="section-title">Order #{{$order->id}}</h1><p class="muted mt-3">Review the complete amount before paying.</p><div class="card p-7 my-8"><div class="flex justify-between py-2"><span>Subtotal</span><span>₹{{number_format($order->subtotal_paise/100,2)}}</span></div><div class="flex justify-between py-2"><span>Discount</span><span>−₹{{number_format($order->discount_paise/100,2)}}</span></div><div class="flex justify-between py-2"><span>Shipping</span><span>₹{{number_format($order->shipping_paise/100,2)}}</span></div><div class="flex justify-between py-2"><span>Tax</span><span>₹{{number_format($order->tax_paise/100,2)}}</span></div><div class="flex justify-between border-t pt-5 mt-3 text-xl font-semibold"><span>Total</span><span>₹{{number_format($order->total_paise/100,2)}}</span></div></div>@if($order->status==='pending_payment' && $order->reservation_expires_at?->isFuture() && config('services.razorpay.key_id'))<button id="pay-button" class="button w-full">Pay securely · ₹{{number_format($order->total_paise/100,2)}}</button><p class="muted text-sm mt-4">Your items are reserved until {{$order->reservation_expires_at->format('H:i')}}. You can return to this page if payment is interrupted.</p><form id="payment-form" method="post" action="{{route('payment.confirm',$order)}}">@csrf<input type="hidden" name="razorpay_order_id"><input type="hidden" name="razorpay_payment_id"><input type="hidden" name="razorpay_signature"></form>@push('scripts')<script src="https://checkout.razorpay.com/v1/checkout.js"></script><script>document.getElementById('pay-button').addEventListener('click',function(){if(typeof Razorpay==='undefined'){alert('Payment gateway could not load. Please retry.');return;}new Razorpay({key:@json(config('services.razorpay.key_id')),amount:@json($order->total_paise),currency:'INR',name:@json($brand),description:'Order #'+@json($order->id),order_id:@json($order->gateway_order_id),prefill:{email:@json($order->email)},handler:function(response){const form=document.getElementById('payment-form');for(const key of ['razorpay_order_id','razorpay_payment_id','razorpay_signature'])form.elements[key].value=response[key];form.submit();}}).open();});</script>@endpush @elseif($order->status==='pending_payment')<p class="error">Payment is not available. Please contact the store before placing another order.</p>@else<a class="button" href="{{route('order.status',$order)}}">View order status</a>@endif</div>@endsection
